  scale_color_gradient(low = "blue", high = "red") +  # Color gradient based on p-value
  theme_minimal() +
  coord_flip() +  # Flip coordinates for better readability
  labs(title = "Top 21:40 Enriched Pathways", 
       x = "Pathway", 
