#### Next is GSEA which is a more robust way to get the involved mechanisms

# 2. with clusterProfiler by Gene Set Enrichment Analysis (GSEA)
# install packages with Biomanager like: 

#if (!require("BiocManager", quietly = TRUE))
#install.packages("BiocManager")
#BiocManager::install("org.Hs.eg.db")

library(clusterProfiler)
library(org.Hs.eg.db)
#library(enrichplot)

# to generate sorted vector based on FC - 
# could be also done by days by exchanging mada with mada_30 or mada_42 respectively
# intersting to do - also to get rid of warning of duplicated gene names?

ranked_genes_fc <- setNames( DEG$avg_log2FC, DEG$Gene) #  remember - how is FC defined in DEG
ranked_genes_fc <- sort(ranked_genes_fc, decreasing = TRUE)

ranked_genes_fc_down <- setNames( DEG$avg_log2FC, DEG$Gene) # again 
ranked_genes_fc_down <- sort(ranked_genes_fc_down, decreasing = TRUE)

ranked_genes_fc_up <- setNames(- DEG$avg_log2FC, DEG$Gene) # again 
ranked_genes_fc_up <- sort(ranked_genes_fc_up, decreasing = TRUE)

# and here you can also change BP to CC and MF - see description
gsea_fc_down <- gseGO(
  geneList = ranked_genes_fc_down,           # Ranked gene list
  OrgDb = org.Hs.eg.db,              # Organism annotation database (human)
  keyType = "SYMBOL",                # Gene identifier type (e.g., SYMBOL, ENTREZID)
  ont = "CC",                        # Ontology type (BP = Biological Process, MF = Molecular Function, CC = Cellular Component)
  minGSSize = 10,                    # Minimum gene set size for testing
  maxGSSize = 500,                   # Maximum gene set size for testing
  pvalueCutoff = 0.05,               # p-value threshold for significance
  verbose = FALSE                    # Suppress verbose output
)

dotplot(gsea_fc_down, showCategory = 10) +
  ggtitle("Top Enriched for Down regulated genes")

gsea_fc_up <- gseGO(
  geneList = ranked_genes_fc_up,           # Ranked gene list
  OrgDb = org.Hs.eg.db,              # Organism annotation database (human)
  keyType = "SYMBOL",                # Gene identifier type (e.g., SYMBOL, ENTREZID)
  ont = "CC",                        # Ontology type (BP = Biological Process, MF = Molecular Function, CC = Cellular Component)
  minGSSize = 10,                    # Minimum gene set size for testing
  maxGSSize = 500,                   # Maximum gene set size for testing
  pvalueCutoff = 0.05,               # p-value threshold for significance
  verbose = FALSE                    # Suppress verbose output
)

dotplot(gsea_fc_up, showCategory = 20) +
  ggtitle("Top Enriched for UP regulated genes")


# to export data to excel

gsea_fc_df_down <- as.data.frame(gsea_fc_down@result)
write.xlsx(gsea_fc_df_down, file = "GSEA_CC_results_down.xlsx")

gsea_fc_df_up <- as.data.frame(gsea_fc_up@result)
write.xlsx(gsea_fc_df_up, file = "GSEA_CC_results_up.xlsx")





